    <div x-show="selectedProduct" x-cloak class="fixed inset-x-4 bottom-4 z-[60] mx-auto max-w-4xl rounded-2xl border border-bordo/10 bg-crema p-4 shadow-2xl sm:inset-x-8 sm:p-5"><div class="grid gap-3 sm:grid-cols-[auto_1fr_auto] sm:items-end"><label class="block"><span class="form-label">Cantidad</span><input type="number" min="1" max="50" x-model.number="detailQuantity" class="form-input w-28"></label><label class="block"><span class="form-label">Nota (opcional)</span><input type="text" maxlength="500" x-model="detailNote" class="form-input" placeholder="Ej: sin nueces, mensaje, colores..."></label><button type="button" @click="addSelectedToCart()" :disabled="!selectedSize || detailQuantity < 1 || detailQuantity > 50" class="btn-primary whitespace-nowrap disabled:cursor-not-allowed disabled:opacity-40">Agregar al carrito <span aria-hidden="true">+</span></button></div><p class="mt-2 text-xs text-ink/50">Se prepara especialmente para tu fecha.</p></div>
